python3 -c "
target = '.....(((((((...((((...((((...((((.........(((((............)))))...))))....((((..........))))...))))...(((........)))...))))..((......))...))))))).....'
print(f'len={len(target)}')

# Compute pairs
stack = []
pairs = {}
for i, c in enumerate(target):
    if c == '(':
        stack.append(i)
    elif c == ')':
        j = stack.pop()
        pairs[j] = i
        pairs[i] = j

# Show pairs sorted by left index
for i in sorted(pairs.keys()):
    if i < pairs[i]:
        print(f'{i} -- {pairs[i]}  ({target[i]} {target[pairs[i]]})')

# Show stems
stems = []
for i in sorted(pairs.keys()):
    if i < pairs[i]:
        if stems and stems[-1][-1][1] + 1 == i and stems[-1][-1][2] - 1 == pairs[i]:
            # extend last stem
            stems[-1].append((i, pairs[i]))
        else:
            stems.append([(i, pairs[i])])

print()
for s in stems:
    print(f'stem: {s[0][0]}-{s[-1][0]}..{s[0][1]}-{s[-1][1]}, len={len(s)}')
    for p in s:
        print(f'  {p[0]} -- {p[1]}')
" 2>&1

